L.Marker.include({
  spin: function (img, time) {
    var div = document.createElement('div');
    div.className = 'spin';
    div.style.backgroundImage = 'url(' + img + ')';
    this.setIcon(new L.DivIcon({
      className: 'spin',
      iconSize: [32, 32]
    }));
    this.on('add', function () {
      this._icon.appendChild(div);
    });
    this.on('remove', function () {
      this._icon.removeChild(div);
    });
    if (time) {
      setTimeout(this.closePopup, time);
    }
  }
});
